import React from "react";

const JobStats = ({ jobs }) => {
  return (
    <div className="stats-grid">
      <div className="stat-card">
        <h3>Total Jobs</h3>
        <div className="value">{jobs.length}</div>
      </div>
      <div className="stat-card">
        <h3>Active</h3>
        <div className="value">{jobs.filter((j) => j.status === "Active").length}</div>
      </div>
      <div className="stat-card">
        <h3>Closed</h3>
        <div className="value">{jobs.filter((j) => j.status === "Closed").length}</div>
      </div>
    </div>
  );
};

export default JobStats;
